<?php
defined( 'ABSPATH' ) || exit;
if(!function_exists('morgenbrot_meta')){function morgenbrot_meta( $post_id, $key ) { return get_post_meta( $post_id, '_morgenbrot_' . $key, true ); }}
function morgenbrot_sanitize_hours( $raw ) { $valid=array();foreach(array_filter(array_map('trim',explode(',',sanitize_text_field($raw))))as$span){if(preg_match('/^([01]\d|2[0-3]):([0-5]\d)\s*-\s*([01]\d|2[0-3]):([0-5]\d)$/',$span,$m))$valid[]=sprintf('%s:%s-%s:%s',$m[1],$m[2],$m[3],$m[4]);}return implode(', ',$valid); }
function morgenbrot_parse_hours( $raw ) { $out=array();foreach(array_filter(array_map('trim',explode(',',(string)$raw)))as$span){if(preg_match('/^(\d{2}):(\d{2})-(\d{2}):(\d{2})$/',$span,$m))$out[]=array($m[1].':'.$m[2],$m[3].':'.$m[4]);}return$out; }
function morgenbrot_location_status( $id, $at=null ) { if(morgenbrot_meta($id,'temporarily_closed'))return array('closed','Vorübergehend geschlossen');$now=$at instanceof DateTimeInterface?DateTimeImmutable::createFromInterface($at):new DateTimeImmutable('now',wp_timezone());$minutes=(int)$now->format('H')*60+(int)$now->format('i');$today=strtolower($now->format('l'));$yesterday=strtolower($now->modify('-1 day')->format('l'));$today_spans=morgenbrot_parse_hours(morgenbrot_meta($id,'hours_'.$today));$yesterday_spans=morgenbrot_parse_hours(morgenbrot_meta($id,'hours_'.$yesterday));if(!$today_spans&&!$yesterday_spans){$has_any=false;foreach(array('monday','tuesday','wednesday','thursday','friday','saturday','sunday')as$day)if(morgenbrot_meta($id,'hours_'.$day)){$has_any=true;break;}if(!$has_any)return array('unknown','Öffnungszeiten auf Anfrage');}foreach($today_spans as$span){$a=((int)substr($span[0],0,2))*60+(int)substr($span[0],3,2);$b=((int)substr($span[1],0,2))*60+(int)substr($span[1],3,2);if(($b>$a&&$minutes>=$a&&$minutes<$b)||($b<=$a&&$minutes>=$a))return array('open','Geöffnet');}foreach($yesterday_spans as$span){$a=((int)substr($span[0],0,2))*60+(int)substr($span[0],3,2);$b=((int)substr($span[1],0,2))*60+(int)substr($span[1],3,2);if($b<=$a&&$minutes<$b)return array('open','Geöffnet');}return array('closed','Geschlossen'); }
function morgenbrot_product_price( $id ) { $regular=(float)morgenbrot_meta($id,'price');$sale=(float)morgenbrot_meta($id,'sale_price');$active=$sale>0&&$sale<$regular;return array('regular'=>$regular,'sale'=>$active?$sale:0,'current'=>$active?$sale:$regular); }
function morgenbrot_format_price( $amount ) { return number_format((float)$amount,2,',','.').' €'; }
function morgenbrot_availability_label($id){$status=morgenbrot_meta($id,'availability_status')?:'in_stock';return array('in_stock'=>'Verfügbar','limited'=>'Begrenzt verfügbar','out_of_stock'=>'Nicht verfügbar')[$status]??'Verfügbar';}
function morgenbrot_migrate_effective_prices(){if(get_option('morgenbrot_data_version')==='2.0.1')return;foreach(get_posts(array('post_type'=>'bakery_product','post_status'=>'any','numberposts'=>-1,'fields'=>'ids'))as$id){$price=morgenbrot_product_price($id);update_post_meta($id,'_morgenbrot_effective_price',$price['current']);}update_option('morgenbrot_data_version','2.0.1',false);}add_action('init','morgenbrot_migrate_effective_prices',30);
function morgenbrot_legacy_preorder_request($vars){if(($vars['pagename']??'')==='vorbestellung')$vars['pagename']='vorbestellen';return$vars;}add_filter('request','morgenbrot_legacy_preorder_request');
function morgenbrot_correct_preorder_url($url,$path){return '/vorbestellung/'===$path?str_replace('/vorbestellung/','/vorbestellen/',$url):$url;}add_filter('home_url','morgenbrot_correct_preorder_url',10,2);
function morgenbrot_product_query( $query ) { if(is_admin()||!$query->is_main_query()||!is_post_type_archive('bakery_product'))return;if(!empty($_GET['produkt_suche']))$query->set('s',sanitize_text_field(wp_unslash($_GET['produkt_suche'])));$tax=[];if(!empty($_GET['kategorie']))$tax[]=['taxonomy'=>'bakery_product_category','field'=>'slug','terms'=>sanitize_title(wp_unslash($_GET['kategorie']))];if($tax)$query->set('tax_query',$tax);$meta=[];foreach(array('vegan','vegetarian','seasonal')as$key)if(!empty($_GET[$key]))$meta[]=['key'=>'_morgenbrot_'.$key,'value'=>'1'];if(!empty($_GET['available']))$meta[]=['key'=>'_morgenbrot_availability_status','value'=>array('in_stock','limited'),'compare'=>'IN'];$sort=sanitize_key($_GET['sort']??'title_asc');if('price_asc'===$sort||'price_desc'===$sort){$query->set('meta_key','_morgenbrot_price');$query->set('orderby','meta_value_num');$query->set('order','price_desc'===$sort?'DESC':'ASC');}else{$query->set('orderby','title');$query->set('order','title_desc'===$sort?'DESC':'ASC');}if($meta)$query->set('meta_query',$meta);$query->set('posts_per_page',9); }
add_action('pre_get_posts','morgenbrot_product_query');
function morgenbrot_effective_price_sort($query){if(is_admin()||!$query->is_main_query()||!is_post_type_archive('bakery_product'))return;$sort=sanitize_key($_GET['sort']??'');if(in_array($sort,array('price_asc','price_desc'),true))$query->set('meta_key','_morgenbrot_effective_price');}add_action('pre_get_posts','morgenbrot_effective_price_sort',20);
function morgenbrot_get_map_locations($ids=array()){ $posts=get_posts(['post_type'=>'bakery_location','post_status'=>'publish','numberposts'=>-1,'post__in'=>$ids?:array()]);$data=[];$day=strtolower(current_datetime()->format('l'));foreach($posts as$post){$lat=(float)morgenbrot_meta($post->ID,'latitude');$lng=(float)morgenbrot_meta($post->ID,'longitude');if(!$lat||!$lng)continue;$status=morgenbrot_location_status($post->ID);$data[]=['id'=>$post->ID,'title'=>$post->post_title,'lat'=>$lat,'lng'=>$lng,'address'=>trim(morgenbrot_meta($post->ID,'street').', '.morgenbrot_meta($post->ID,'postal_code').' '.morgenbrot_meta($post->ID,'city')),'status'=>$status[1],'statusClass'=>$status[0],'hours'=>morgenbrot_meta($post->ID,'hours_'.$day),'url'=>get_permalink($post)];}return$data; }
function morgenbrot_preorder_columns($columns){return array('cb'=>$columns['cb'],'title'=>'Anfrage','morgenbrot_customer'=>'Kunde','morgenbrot_pickup'=>'Abholung','morgenbrot_status'=>'Status','date'=>'Eingang');}add_filter('manage_bakery_preorder_posts_columns','morgenbrot_preorder_columns');
function morgenbrot_preorder_column($column,$post_id){$data=(array)get_post_meta($post_id,'_morgenbrot_order',true);if('morgenbrot_customer'===$column)echo esc_html(($data['name']??'').' · '.($data['email']??''));if('morgenbrot_pickup'===$column)echo esc_html(($data['pickup']??'').' · '.($data['location_name']??''));if('morgenbrot_status'===$column)echo esc_html(get_post_meta($post_id,'_morgenbrot_status',true));}add_action('manage_bakery_preorder_posts_custom_column','morgenbrot_preorder_column',10,2);
function morgenbrot_export_orders(){if(!current_user_can('manage_options'))wp_die('Nicht erlaubt');check_admin_referer('morgenbrot_export_orders');nocache_headers();header('Content-Type: text/csv; charset=UTF-8');header('Content-Disposition: attachment; filename="morgenbrot-vorbestellungen.csv"');$out=fopen('php://output','w');fwrite($out,"\xEF\xBB\xBF");fputcsv($out,['Datum','Name','E-Mail','Telefon','Filiale','Abholung','Artikel','Status']);foreach(get_posts(['post_type'=>'bakery_preorder','post_status'=>'any','numberposts'=>-1])as$post){$d=(array)get_post_meta($post->ID,'_morgenbrot_order',true);$cells=[$post->post_date,$d['name']??'',$d['email']??'',$d['phone']??'',$d['location_name']??'',$d['pickup']??'',$d['items_text']??'',get_post_meta($post->ID,'_morgenbrot_status',true)];$cells=array_map(function($v){$v=(string)$v;return preg_match('/^[=+\-@]/',$v)?"'".$v:$v;},$cells);fputcsv($out,$cells);}fclose($out);exit;}add_action('admin_post_morgenbrot_export_orders','morgenbrot_export_orders');add_filter('views_edit-bakery_preorder',function($views){if(current_user_can('manage_options'))$views['export']='<a href="'.esc_url(wp_nonce_url(admin_url('admin-post.php?action=morgenbrot_export_orders'),'morgenbrot_export_orders')).'">CSV exportieren</a>';return$views;});
